cypress_script:
describe('Product List Search Functionality', () => {
  it('should display relevant products when a valid product name is searched', () => {
    cy.visit('https://automationexercise.com/products');
    cy.get('#search_product').type('Tshirt');
    cy.get('#submit_search').click();
    cy.url().should('include', 'products');
    cy.get('.google-anno').should('be.visible');
  });
  it('should not change the URL or hide the product list when search is submitted empty', () => {
    cy.visit('https://automationexercise.com/products');
    cy.get('#submit_search').click();
    cy.url().should('eq', 'https://automationexercise.com/products');
    cy.get('#accordian').should('be.visible');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Product List Search Functionality', () => {
  test('should display relevant products when a valid product name is searched', async ({ page }) => {
    await page.goto('https://automationexercise.com/products');
    await page.fill('#search_product', 'Tshirt');
    await page.click('#submit_search');
    await expect(page).toHaveURL(/products/);
    await expect(page.locator('.google-anno')).toBeVisible();
  });
  test('should not change the URL or hide the product list when search is submitted empty', async ({ page }) => {
    await page.goto('https://automationexercise.com/products');
    await page.click('#submit_search');
    await expect(page).toHaveURL('https://automationexercise.com/products');
    await expect(page.locator('#accordian')).toBeVisible();
  });
});
